head.b:skin:
/* === SKELETON LOADER (Cacing) === */
.skeleton {
  background: #e2e8f0;
  background: linear-gradient(90deg, #f1f5f9 25%, #f8fafc 50%, #f1f5f9 75%);
  background-size: 200% 100%;
  animation: skeleton-loading 1.5s infinite;
  border-radius: 8px;
  position: relative;
  overflow: hidden;
}
@keyframes skeleton-loading {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
.skeleton-text { height: 14px; margin-bottom: 8px; width: 100%; }
.skeleton-text.short { width: 60%; }
.skeleton-title { height: 24px; margin-bottom: 12px; width: 40%; }
.skeleton-card { height: 120px; width: 100%; }
.skeleton-circle { width: 48px; height: 48px; border-radius: 50%; }

.is-loading .hide-on-load { display: none !important; }
.is-loading .show-on-load { display: block !important; }
.show-on-load { display: none; }

@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
@keyframes pulseScale { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.05); } }

/* --- DASHBOARD CSS --- */
:root {



  --primary: #10b981;

  --primary-dark: #059669;

  --primary-light: #d1fae5;

  --secondary: #0f172a;

  --secondary-light: #1e293b;

  --surface: #ffffff;

  --background: #f8fafc;

  --text-main: #1e293b;

  --text-muted: #64748b;

  --border: #e2e8f0;

  --danger: #ef4444;

  --warning: #f59e0b;

  --success: #10b981;





  --radius-md: 8px;

  --radius-lg: 12px;

  --radius-xl: 16px;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.04);

  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07);

  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08);

}





* {

  margin: 0;

  padding: 0;

  box-sizing: border-box;

}



.dashboard-active { display: flex; height: 100vh; overflow: hidden; 

  font-family: 'Outfit', sans-serif;

  background: var(--background);

  color: var(--text-main);

  display: flex;

  height: 100vh;

  overflow: hidden;

}



.dashboard-active .sidebar {

  width: 260px;

  background-color: var(--secondary);

  color: white;

  display: flex;

  flex-direction: column;

  height: 100%;

  flex-shrink: 0;

  transition: transform 0.3s ease;

  z-index: 100;

}



.dashboard-active .brand {

  padding: 24px;

  font-size: 24px;

  font-weight: 700;

  color: var(--primary);

  display: flex;

  align-items: center;

  gap: 12px;

  letter-spacing: -0.5px;

}



.dashboard-active .brand i {

  color: var(--surface);

}



.dashboard-active .nav-menu {

  padding: 0 16px;

  flex: 1;

}



.dashboard-active .nav-item {

  display: flex;

  align-items: center;

  gap: 14px;

  padding: 14px 16px;

  border-radius: var(--radius-lg);

  cursor: pointer;

  color: #94a3b8;

  font-size: 15px;

  transition: all 0.2s;

  margin-bottom: 4px;

}



.dashboard-active .nav-item:hover {

  background: var(--secondary-light);

  color: white;

}



.dashboard-active .nav-item.active {

  background: var(--primary);

  color: white;

  font-weight: 600;

}



.dashboard-active .main-content {

  flex: 1;

  overflow-y: auto;

  background: var(--background);

}



.dashboard-active .top-bar {

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 20px 32px;

  background: var(--surface);

  border-bottom: 1px solid var(--border);

  position: sticky;

  top: 0;

  z-index: 100;

}



.dashboard-active .mobile-toggle {

  display: none;

  background: none;

  border: none;

  font-size: 20px;

  cursor: pointer;

}



.dashboard-active .page-title h2 {

  font-size: 22px;

  font-weight: 700;

}



.dashboard-active .page-title p {

  color: var(--text-muted);

  font-size: 14px;

}



.dashboard-active .user-mini {

  padding: 16px;

  display: flex;

  align-items: center;

  gap: 12px;

  border-top: 1px solid var(--secondary-light);

}



.dashboard-active .avatar {

  width: 36px;

  height: 36px;

  border-radius: 50%;

  background: var(--primary);

  display: flex;

  align-items: center;

  justify-content: center;

  font-weight: 600;

  font-size: 14px;

  color: white;

}



.dashboard-active .user-info {

  flex: 1;

}



.dashboard-active .user-info h4 {

  font-size: 14px;

  font-weight: 600;

}



.dashboard-active .user-info span {

  font-size: 12px;

  color: #94a3b8;

  display: block;

}



.dashboard-active .logout-btn {

  color: var(--danger);

  background: none;

  border: none;

  cursor: pointer;

  font-size: 16px;

  padding: 8px;

  transition: transform 0.2s;

}



.dashboard-active .logout-btn:hover {

  transform: scale(1.1);

}



.dashboard-active .actions {

  display: flex;

  gap: 8px;

}



.dashboard-active .btn {

  padding: 10px 20px;

  border-radius: var(--radius-md);

  border: none;

  font-family: inherit;

  font-weight: 500;

  cursor: pointer;

  display: inline-flex;

  align-items: center;

  gap: 8px;

  transition: all 0.2s;

}



.dashboard-active .btn-primary {

  background-color: var(--primary);

  color: white;

  box-shadow: var(--shadow-sm);

}



.dashboard-active .btn-primary:hover {

  background-color: var(--primary-dark);

  transform: translateY(-1px);

}



.dashboard-active .btn-outline {

  background: transparent;

  border: 1px solid var(--border);

  color: var(--text-main);

}



.dashboard-active .btn-outline:hover {

  background: var(--surface);

  border-color: var(--text-muted);

}



.dashboard-active .btn-danger {

  background-color: var(--danger);

  color: white;

}



.dashboard-active .btn-danger:hover {

  background-color: #dc2626;

}





.dashboard-active .content-wrapper {

  padding: 32px;

  max-width: 1400px;

  margin: 0 auto;

}





.dashboard-active .page-section {

  display: none;

  animation: fadeIn 0.3s ease-out;

}



.dashboard-active .page-section.active {

  display: block;

}



@keyframes fadeIn {

  from {

    opacity: 0;

    transform: translateY(10px);

  }



  to {

    opacity: 1;

    transform: translateY(0);

  }

}





.dashboard-active .hero-card {

  background: linear-gradient(135deg, #059669 0%, #10b981 100%);

  border-radius: var(--radius-xl);

  padding: 40px;

  color: white;

  margin-bottom: 32px;

  position: relative;

  overflow: hidden;

  box-shadow: var(--shadow-lg);

}



.dashboard-active .hero-bg-icon {

  position: absolute;

  right: -20px;

  bottom: -20px;

  font-size: 200px;

  opacity: 0.05;

  transform: rotate(-15deg);

}



.dashboard-active .hero-content {

  position: relative;

  z-index: 2;

  max-width: 600px;

}









.dashboard-active .skeleton, .dashboard-active .skeleton-text, .dashboard-active .skeleton-title, .dashboard-active .skeleton-card, .dashboard-active .skeleton-circle {

  background: #e2e8f0;

  background: linear-gradient(110deg, #e2e8f0 30%, #f8fafc 50%, #e2e8f0 70%);

  background-size: 300% 100%;

  animation: skeletonShimmer 1.8s ease-in-out infinite;

  border-radius: var(--radius-md);

  position: relative;

  overflow: hidden;

}



@keyframes skeletonShimmer {

  0% {
    background-position: 300% 0;
  }

  100% {
    background-position: -300% 0;
  }

}



.dashboard-active .skeleton-text {
  height: 14px;
  margin-bottom: 8px;
  width: 100%;
}

.dashboard-active .skeleton-text.short {
  width: 60%;
}

.dashboard-active .skeleton-title {
  height: 24px;
  margin-bottom: 12px;
  width: 40%;
}

.dashboard-active .skeleton-card {
  height: 120px;
  width: 100%;
}

.dashboard-active .skeleton-circle {
  width: 48px;
  height: 48px;
  border-radius: 50%;
}









@keyframes renderIn {

  from {
    opacity: 0;
    transform: translateY(24px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }

}



.dashboard-active .is-loading .top-bar {
  animation: renderIn 0.45s ease-out 0.05s both;
}

.dashboard-active .is-loading .hero-card {
  animation: renderIn 0.5s ease-out 0.12s both;
}

.dashboard-active .is-loading


.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
  margin-bottom: 30px;
}

.dashboard-active .card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
  margin-bottom: 24px;
}

.dashboard-active .admin-stats-card {
  padding: 24px;
  margin-bottom: 24px;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  background: var(--surface);
}


.dashboard-active .is-loading .dashboard-split {
  animation: renderIn 0.5s ease-out 0.34s both;
}





.dashboard-active .is-loading .stat-card:nth-child(1) {
  animation: renderIn 0.4s ease-out 0.15s both;
}

.dashboard-active .is-loading .stat-card:nth-child(2) {
  animation: renderIn 0.4s ease-out 0.22s both;
}

.dashboard-active .is-loading .stat-card:nth-child(3) {
  animation: renderIn 0.4s ease-out 0.29s both;
}

.dashboard-active .is-loading .stat-card:nth-child(4) {
  animation: renderIn 0.4s ease-out 0.36s both;
}

.dashboard-active .is-loading .stat-card:nth-child(5) {
  animation: renderIn 0.4s ease-out 0.43s both;
}

.dashboard-active .is-loading .stat-card:nth-child(6) {
  animation: renderIn 0.4s ease-out 0.50s both;
}



















.dashboard-active .is-loading


.card, .dashboard-active .stat-card, .dashboard-active .hero-card, .dashboard-active .page-section {

  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.4s ease;

}



.dashboard-active .refreshing-card {

  opacity: 0.5;

  transform: scale(0.98);

  filter: blur(1px);

}



.dashboard-active .hero-content h2 {

  font-size: 28px;

  margin-bottom: 12px;

}



.dashboard-active .hero-content p {

  color: #cbd5e1;

  margin-bottom: 24px;

}



.dashboard-active .url-input-group {

  display: flex;

  background: white;

  padding: 8px;

  border-radius: var(--radius-lg);

  box-shadow: var(--shadow-md);

}



.dashboard-active .url-input-group input {

  flex: 1;

  border: none;

  padding: 12px 20px;

  font-size: 16px;

  outline: none;

  font-family: inherit;

}



.dashboard-active .url-input-group button {

  border-radius: var(--radius-md);

  padding: 12px 32px;

  font-size: 16px;

}





.dashboard-active .stats-grid {

  display: grid;

  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));

  gap: 16px;

  margin-bottom: 32px;

}



.dashboard-active .stat-card {

  background: var(--surface);

  padding: 24px;

  border-radius: var(--radius-xl);

  box-shadow: var(--shadow-sm);

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  border: 1px solid var(--border);

}



.dashboard-active .stat-info h3 {

  font-size: 14px;

  color: var(--text-muted);

  font-weight: 500;

  margin-bottom: 8px;

}



.dashboard-active .stat-info .value {

  font-size: 24px;

  font-weight: 700;

  color: var(--secondary);

}



.dashboard-active .stat-icon {

  width: 48px;

  height: 48px;

  border-radius: var(--radius-lg);

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 20px;

}



.dashboard-active .icon-green {

  background: var(--primary-light);

  color: var(--primary);

}



.dashboard-active .icon-blue {

  background: #dbeafe;

  color: #2563eb;

}



.dashboard-active .icon-orange {

  background: #ffedd5;

  color: #ea580c;

}



.dashboard-active .icon-purple {

  background: #f3e8ff;

  color: #9333ea;

}





.dashboard-active .dashboard-split {

  display: grid;

  grid-template-columns: 2fr 1fr;

  gap: 32px;

}



.dashboard-active .card {

  background: var(--surface);

  border-radius: var(--radius-xl);

  padding: 24px;

  box-shadow: var(--shadow-sm);

  border: 1px solid var(--border);

}



.dashboard-active .card-header {

  display: flex;

  justify-content: space-between;

  align-items: center;

  margin-bottom: 24px;

}



.dashboard-active .card-title {

  font-size: 18px;

  font-weight: 600;

}



.dashboard-active .activity-list {

  list-style: none;

}



.dashboard-active .activity-item {

  display: flex;

  gap: 16px;

  padding: 16px 0;

  border-bottom: 1px solid var(--border);

}



.dashboard-active .activity-item:last-child {

  border-bottom: none;

}



.dashboard-active .activity-icon {

  width: 40px;

  height: 40px;

  border-radius: 50%;

  background: var(--background);

  display: flex;

  align-items: center;

  justify-content: center;

  color: var(--text-muted);

}



.dashboard-active .activity-details h4 {

  font-size: 14px;

  font-weight: 600;

  margin-bottom: 4px;

}



.dashboard-active .activity-details p {

  font-size: 12px;

  color: var(--text-muted);

}





.dashboard-active .shortlink-result {

  margin-top: 20px;

  background: rgba(255, 255, 255, 0.1);

  padding: 16px;

  border-radius: var(--radius-md);

  display: none;

  border: 1px solid rgba(255, 255, 255, 0.2);

}



.dashboard-active .shortlink-text {

  font-family: monospace;

  font-size: 18px;

  color: white;

  margin-bottom: 10px;

  display: block;

}



.dashboard-active .copy-btn {

  width: 100%;

  background: white;

  color: var(--secondary);

  border: none;

  padding: 10px;

  border-radius: 4px;

  cursor: pointer;

  font-weight: 600;

}





.dashboard-active .form-group {

  margin-bottom: 20px;

}



.dashboard-active .form-group label {

  display: block;

  margin-bottom: 8px;

  font-weight: 500;

  font-size: 14px;

}



.dashboard-active .form-group input, .dashboard-active .form-group select {

  width: 100%;

  padding: 12px;

  border: 1px solid var(--border);

  border-radius: var(--radius-md);

  font-family: inherit;

  font-size: 14px;

  transition: border-color 0.2s;

}



.dashboard-active .form-group input:focus, .dashboard-active .form-group select:focus {

  outline: none;

  border-color: var(--primary);

  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.1);

}





.dashboard-active .wallet-hero {

  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);

  border-radius: var(--radius-xl);

  padding: 32px;

  color: white;

  margin-bottom: 24px;

  position: relative;

  overflow: hidden;

}



.dashboard-active .wallet-hero .hero-bg-icon {

  font-size: 150px;

  opacity: 0.04;

}



.dashboard-active .wallet-balance-label {

  font-size: 14px;

  color: #94a3b8;

  margin-bottom: 8px;

}



.dashboard-active .wallet-balance-value {

  font-size: 36px;

  font-weight: 700;

  color: var(--primary);

}



.dashboard-active .wallet-stats-row {

  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 16px;

  margin-top: 20px;

}



.dashboard-active .wallet-stat-item {

  background: rgba(255, 255, 255, 0.06);

  padding: 16px;

  border-radius: var(--radius-lg);

  border: 1px solid rgba(255, 255, 255, 0.08);

}



.dashboard-active .wallet-stat-item .label {

  font-size: 12px;

  color: #94a3b8;

  margin-bottom: 4px;

}



.dashboard-active .wallet-stat-item .val {

  font-size: 18px;

  font-weight: 600;

}



.dashboard-active .wallet-stat-item .val.pending {

  color: #f59e0b;

}



.dashboard-active .wallet-stat-item .val.success {

  color: #10b981;

}



.dashboard-active .wallet-grid {

  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 24px;

}





.dashboard-active .history-tabs {

  display: flex;

  gap: 4px;

  background: var(--background);

  padding: 4px;

  border-radius: var(--radius-lg);

  margin-bottom: 24px;

  border: 1px solid var(--border);

}



.dashboard-active .history-tab {

  flex: 1;

  padding: 12px 20px;

  border: none;

  background: transparent;

  font-family: inherit;

  font-size: 14px;

  font-weight: 500;

  cursor: pointer;

  border-radius: var(--radius-md);

  color: var(--text-muted);

  transition: all 0.2s;

}



.dashboard-active .history-tab.active {

  background: var(--surface);

  color: var(--primary);

  font-weight: 600;

  box-shadow: var(--shadow-sm);

}



.dashboard-active .history-tab:hover:not(.active) {

  color: var(--text-main);

}



.dashboard-active .history-content {

  display: none;

}



.dashboard-active .history-content.active {

  display: block;

  animation: fadeIn 0.3s ease-out;

}



.dashboard-active .history-table {

  width: 100%;

  border-collapse: collapse;

}



.dashboard-active .history-table thead th {

  text-align: left;

  padding: 12px 16px;

  font-size: 12px;

  font-weight: 600;

  color: var(--text-muted);

  text-transform: uppercase;

  letter-spacing: 0.05em;

  background: var(--background);

  border-bottom: 1px solid var(--border);

}



.dashboard-active .history-table tbody td {

  padding: 14px 16px;

  font-size: 14px;

  border-bottom: 1px solid var(--border);

}



.dashboard-active .history-table tbody tr:hover {

  background: var(--background);

}



.dashboard-active .status-badge {

  display: inline-block;

  padding: 4px 12px;

  border-radius: 20px;

  font-size: 12px;

  font-weight: 600;

}



.dashboard-active .status-badge.pending {

  background: #fef3c7;

  color: #b45309;

}



.dashboard-active .status-badge.success {

  background: #d1fae5;

  color: #065f46;

}



.dashboard-active .status-badge.rejected {

  background: #fee2e2;

  color: #991b1b;

}



.dashboard-active .empty-state {

  text-align: center;

  padding: 48px 20px;

  color: var(--text-muted);

}



.dashboard-active .empty-state i {

  font-size: 48px;

  margin-bottom: 16px;

  opacity: 0.3;

}



.dashboard-active .empty-state p {

  font-size: 14px;

}





.dashboard-active .settings-grid {

  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 24px;

}



.dashboard-active .settings-card {

  background: var(--surface);

  border-radius: var(--radius-xl);

  padding: 28px;

  box-shadow: var(--shadow-sm);

  border: 1px solid var(--border);

}



.dashboard-active .settings-card-header {

  display: flex;

  align-items: center;

  gap: 12px;

  margin-bottom: 24px;

  padding-bottom: 16px;

  border-bottom: 1px solid var(--border);

}



.dashboard-active .settings-card-header .icon-circle {

  width: 40px;

  height: 40px;

  border-radius: 50%;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 16px;

}



.dashboard-active .settings-card-header h3 {

  font-size: 16px;

  font-weight: 600;

}



.dashboard-active .settings-card-header p {

  font-size: 12px;

  color: var(--text-muted);

}



.dashboard-active .current-info {

  background: var(--background);

  padding: 12px 16px;

  border-radius: var(--radius-md);

  margin-bottom: 20px;

  font-size: 13px;

  color: var(--text-muted);

  border: 1px solid var(--border);

}



.dashboard-active .current-info strong {

  color: var(--text-main);

}





.dashboard-active .loading-row {

  text-align: center;

  padding: 32px;

  color: var(--text-muted);

}



.dashboard-active .loading-row i {

  margin-right: 8px;

}





@media (max-width: 1024px) {

  .dashboard-active .dashboard-split {

    grid-template-columns: 1fr;

  }



  .dashboard-active .wallet-grid {

    grid-template-columns: 1fr;

  }



  .dashboard-active .settings-grid {

    grid-template-columns: 1fr;

  }

}



@media (max-width: 768px) {

  .dashboard-active { display: flex; height: 100vh; overflow: hidden; 

    overflow: auto;

    height: auto;

  }



  .dashboard-active .sidebar {

    position: fixed;

    left: 0;

    top: 0;

    height: 100%;

    transform: translateX(-260px);

    transition: transform 0.3s ease;

    z-index: 200;

  }



  .dashboard-active .sidebar.active {

    transform: translateX(0);

  }



  .dashboard-active .sidebar-overlay {

    display: none;

    position: fixed;

    inset: 0;

    background: rgba(0, 0, 0, 0.45);

    z-index: 199;

  }



  .dashboard-active .sidebar-overlay.show {

    display: block;

  }



  .dashboard-active .mobile-toggle {

    display: flex;

    align-items: center;

    justify-content: center;

    width: 40px;

    height: 40px;

    border-radius: 10px;

    background: var(--background);

    border: 1px solid var(--border);

    color: var(--text-main);

  }



  .dashboard-active .main-content {

    width: 100%;

  }



  .dashboard-active .top-bar {

    padding: 14px 16px;

    gap: 12px;

  }



  .dashboard-active .content-wrapper {

    padding: 16px;

  }



  .dashboard-active .stats-grid {

    grid-template-columns: repeat(2, 1fr);

    gap: 12px;

  }



  .dashboard-active .stat-card {

    padding: 16px;

  }



  .dashboard-active .stat-info .value {

    font-size: 20px;

  }



  .dashboard-active .wallet-stats-row {

    grid-template-columns: 1fr;

  }



  .dashboard-active .hero-card {

    padding: 24px 20px;

  }



  .dashboard-active .hero-content h2 {

    font-size: 20px;

  }



  .dashboard-active .url-input-group {

    flex-direction: column;

    gap: 8px;

  }



  .dashboard-active .url-input-group button {

    width: 100%;

    justify-content: center;

  }



  .dashboard-active .history-table {

    font-size: 13px;

  }



  .dashboard-active .history-table th, .dashboard-active .history-table td {

    padding: 10px 10px;

  }

}



@media (max-width: 480px) {

  .dashboard-active .stats-grid {

    grid-template-columns: 1fr 1fr;

    gap: 10px;

  }



  .dashboard-active .page-title h2 {

    font-size: 17px;

  }



  .dashboard-active .page-title p {

    display: none;

  }



  .dashboard-active .stat-card {

    padding: 14px 12px;

  }

}





.dashboard-active .admin-table-responsive {

  overflow-x: auto;

  -webkit-overflow-scrolling: touch;

  margin-bottom: 1rem;

  border-radius: var(--radius-md);

  box-shadow: inset 0 0 0 1px var(--border);

}



.dashboard-active .admin-table {

  width: 100%;

  border-collapse: collapse;

}



.dashboard-active .admin-table th {

  text-align: left;

  padding: 12px 16px;

  font-size: 12px;

  color: var(--text-muted);

  text-transform: uppercase;

  border-bottom: 1px solid var(--border);

  background: var(--background);

}



.dashboard-active .admin-table td {

  padding: 14px 16px;

  font-size: 14px;

  border-bottom: 1px solid var(--border);

}



.dashboard-active .admin-table tr:hover {

  background: var(--background);

}



@media (max-width: 768px) {



  .dashboard-active .admin-table th, .dashboard-active .admin-table td {

    font-size: 13px;

    padding: 10px 8px;

    white-space: nowrap;

  }


  .dashboard-active .stats-grid {

    grid-template-columns: repeat(2, 1fr);

    gap: 12px;

  }


  .dashboard-active .admin-table .btn-sm {
    min-width: 32px;
    min-height: 32px;
    padding: 6px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .dashboard-active .admin-table-responsive {
    padding-bottom: 10px;

  }


}

@media (max-width: 480px) {

  .dashboard-active .stats-grid {

    grid-template-columns: 1fr;

  }


  .dashboard-active #btn-broadcast {
    width: 100%;
  }

  .dashboard-active #broadcast-message {
    width: 100%;
  }

}



@keyframes progressShimmer {

  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }

}


@keyframes shimmer {
  0% {
    background-position: -400px 0;
  }

  100% {
    background-position: 400px 0;
  }
}

.dashboard-active .shimmer-line {
  background: linear-gradient(90deg, #e2e8f0 25%, #f1f5f9 37%, #e2e8f0 63%);
  background-size: 800px 100%;
  animation: shimmer 1.4s ease infinite;
  border-radius: 6px;
}

.dashboard-active #page-shimmer {
  position: fixed;
  inset: 0;
  z-index: 9998;
  background: var(--background);
  display: flex;
  transition: opacity 0.4s ease;
}

.dashboard-active #page-shimmer.fade-out {
  opacity: 0;
  pointer-events: none;
}

.dashboard-active .shimmer-sidebar {
  width: 260px;
  background: var(--secondary);
  padding: 24px 16px;
  flex-shrink: 0;
}

.dashboard-active .shimmer-sidebar-brand {
  height: 28px;
  width: 120px;
  border-radius: 6px;
  margin-bottom: 32px;
  background: rgba(255, 255, 255, 0.1);
}

.dashboard-active .shimmer-sidebar-item {
  height: 42px;
  border-radius: 10px;
  margin-bottom: 6px;
  background: rgba(255, 255, 255, 0.06);
}

.dashboard-active .shimmer-main {
  flex: 1;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.dashboard-active .shimmer-topbar {
  height: 64px;
  background: white;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 24px;
  gap: 16px;
}

.dashboard-active .shimmer-content {
  flex: 1;
  padding: 24px;
  overflow: hidden;
}

.dashboard-active .shimmer-hero {
  height: 160px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--primary), #0d9488);
  margin-bottom: 24px;
  padding: 28px;
  position: relative;
  overflow: hidden;
}

.dashboard-active .shimmer-hero-line {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  margin-bottom: 12px;
}

.dashboard-active .shimmer-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

.dashboard-active .shimmer-stat-card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 20px;
  border: 1px solid var(--border);
}

.dashboard-active .shimmer-charts {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 16px;
}

.dashboard-active .shimmer-chart-card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 20px;
  border: 1px solid var(--border);
  min-height: 200px;
}

@media (max-width: 768px) {
  .dashboard-active .shimmer-sidebar {
    display: none;
  }

  .dashboard-active .shimmer-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .dashboard-active .shimmer-charts {
    grid-template-columns: 1fr;
  }
}


.dashboard-active .save-rekening-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  margin-top: 4px;
  border-top: 1px dashed var(--border);
}

.dashboard-active .save-rekening-row label {
  font-size: 13px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.dashboard-active .save-rekening-row label i {
  color: var(--primary);
}

.dashboard-active .toggle-switch {
  position: relative;
  width: 44px;
  height: 24px;
  flex-shrink: 0;
}

.dashboard-active .toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.dashboard-active .toggle-slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background: #cbd5e1;
  border-radius: 24px;
  transition: 0.3s;
}

.dashboard-active .toggle-slider:before {
  content: "";
  position: absolute;
  height: 18px;
  width: 18px;
  left: 3px;
  bottom: 3px;
  background: white;
  border-radius: 50%;
  transition: 0.3s;
}

.dashboard-active .toggle-switch input:checked+.toggle-slider {
  background: var(--primary);
}

.dashboard-active .toggle-switch input:checked+.toggle-slider:before {
  transform: translateX(20px);
}

.dashboard-active .saved-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--primary);
  background: #ecfdf5;
  padding: 4px 10px;
  border-radius: 20px;
  font-weight: 600;
  margin-left: 8px;
}

.dashboard-active .saved-badge i {
  font-size: 11px;
}

.dashboard-active .btn-clear-saved {
  background: none;
  border: none;
  color: #ef4444;
  font-size: 12px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: 0.2s;
}

.dashboard-active .btn-clear-saved:hover {
  background: #fee2e2;
}


  @keyframes shimmer {
    0% {
      background-position: -400px 0
    }

    100% {
      background-position: 400px 0
    }
  }

  .dashboard-active .shimmer-line {
    background: linear-gradient(90deg, #e2e8f0 25%, #f1f5f9 37%, #e2e8f0 63%);
    background-size: 800px 100%;
